87:export async function createIssue(gh, repo, { title, body, labels = [] }) {
88-  const { status, json } = await gh(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels } });
89-  // The STATUS is read, not just the body (#the-fleet-froze-on-this): a 403 from a
90-  // repo whose Actions cannot create issues puts an error object where the issue
91-  // should be, and a body-only destructure turns that refusal into a plausible
92-  // object whose `.number` is simply undefined.
93-  return { status, number: status >= 200 && status < 300 ? json?.number ?? null : null, json };
94-}
95-
96-// The one write here that is not an issue mutation: fire a `workflow_dispatch`.
97-// It is how the queue CHAINS (DESIGN §10) — a run that settled its item starts a
98-// fresh one rather than leaving the remainder for the cron — and `workflow_dispatch`
99-// is one of the two events the default `GITHUB_TOKEN` may fire, the explicit
100-// exemption in the same recursion guard that suppresses its label events, so no
101-// wider credential is involved.
===
// The families a request may ask for in its `Model:` field. `none` is not among
// them: a request is implemented by a session, so an agentless family would name a
// run that cannot happen.
export const REQUEST_MODELS = Object.freeze(['opus', 'sonnet', 'haiku']);

// The four state labels an open item may wear. An open item wearing none of them
// and no `needs-human` is off the state machine entirely — a torn label swap's
// leavings, which the janitor repairs (DESIGN §6.2, §11).
export const STATE_LABELS = [BLOCKED, READY, EXECUTING, AGENT];

